window.MGProseData("8475bf93bff23402dcd2a557a892da2171153f6e55b25bd45d2da50e00c7fc81",{"html":"\u003cp>结论为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmtext>最小值不被达到\u003c/mtext>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{e_0=0,\\qquad \\text{最小值不被达到},\\qquad\n(\\pi_1(u_j),\\ldots,\\pi_4(u_j))\n\\longrightarrow\n\\left(\\frac1{10},\\frac3{10},\\frac3{10},\\frac3{10}\\right)}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中最后一个结论适用于任意近最优序列。题述从“两两没有秩一连接”推出四相系统存在正能隙的论证不成立。下面直接构造位移并证明这些结论。\u003c/p>\n\u003cp>先引入四个中间梯度\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nP_0=0,\\quad P_1=\\operatorname{diag}(0,1),\\quad\nP_2=\\operatorname{diag}(1,1),\\quad P_3=\\operatorname{diag}(1,0).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它们满足以下循环分裂：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\nP_0\u0026amp;=\\tfrac14A_4+\\tfrac34P_1,\\\\\nP_1\u0026amp;=\\tfrac13A_3+\\tfrac23P_2,\\\\\nP_2\u0026amp;=\\tfrac12A_2+\\tfrac12P_3,\\\\\nP_3\u0026amp;=\\tfrac13A_1+\\tfrac23P_0.\n\\end{aligned} \\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n每一行右端两个矩阵的差都具有秩一。完成一轮后，剩余的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 比例为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>6\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac34\\frac23\\frac12\\frac23=\\frac16.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n下面将这些分裂实现为满足全部约束的位移。\u003c/p>\n\u003cp>设某个矩形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内当前位移为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Fx+c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，需要实现\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>θ\u003c/mi>\u003cmi>W\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>θ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF=\\theta W+(1-\\theta)G,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>W\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F,W,G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 来自 (1) 的同一行，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为井，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为剩余梯度。记它们发生变化的对角方向为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，另一方向为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\ell\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。具体参数为\u003c/p>\n\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/th>\n\u003cth>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/th>\n\u003cth>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/th>\n\u003cth>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>θ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/th>\n\u003cth>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003c/tbody>\n\u003c/table>\n\u003cp>用相应坐标写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>b\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nR=\\{a\u0026lt;x_k\u0026lt;a+L,\\ b\u0026lt;x_\\ell\u0026lt;b+H\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>δ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;\\delta\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义横向截止函数\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>H\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>b\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>H\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\eta(t)=\\min\\left\\{1,\\frac{2(t-b)}{\\delta H},\n                    \\frac{2(b+H-t)}{\\delta H}\\right\\},\n\\qquad b\\le t\\le b+H.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它在两端为零，在长度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>δ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(1-\\delta)H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的中间区间恒为一，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsup>\u003cmi>η\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\eta\u0026#x27;|\\le\\frac2{\\delta H}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>W\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>W\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>G\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nd_W=W_{kk}-F_{kk},\\qquad d_G=G_{kk}-F_{kk}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取连续、分段线性的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-周期函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varphi\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmi>φ\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>W\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>θ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>G\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>θ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varphi(0)=0,\\qquad\n\\varphi\u0026#x27;(s)=\n\\begin{cases}\nd_W,\u0026amp;0\u0026lt;s\u0026lt;\\theta,\\\\\nd_G,\u0026amp;\\theta\u0026lt;s\u0026lt;1.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>θ\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>W\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>θ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>G\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta d_W+(1-\\theta)d_G=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，确有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varphi(1)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故周期延拓连续。表中各情形均满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>W\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmi>G\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>φ\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmn>3.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|d_W|,|d_G|\\le3,\\qquad \\|\\varphi\\|_\\infty\\le3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n选取整数\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>6\u003c/mn>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>ρ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nm\\ge\\max\\left\\{1,\\frac{6L}{\\delta H}\\right\\},\\qquad \\rho=\\frac Lm,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>ρ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>φ\u003c/mi>\u003cmtext> ⁣\u003c/mtext>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmi>ρ\u003c/mi>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nh(t)=\\rho\\,\\varphi\\!\\left(\\frac{t-a}{\\rho}\\right),\\qquad\nw_R(x)=h(x_k)\\eta(x_\\ell)e_k.\n\\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h(a)=h(a+L)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>R\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w_R=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 于整个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。将其零延拓后加入当前位移，既能与矩形外位移连续拼接，也保持外边界条件。\u003c/p>\n\u003cp>在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内，新梯度为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>η\u003c/mi>\u003cmsup>\u003cmi>h\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>⊗\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>h\u003c/mi>\u003cmsup>\u003cmi>η\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>⊗\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nF+\\eta h\u0026#x27;e_k\\otimes e_k+h\\eta\u0026#x27;e_k\\otimes e_\\ell.\n\\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中对角部分位于线段 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>W\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[W,G]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上，故其 Frobenius 范数平方不超过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>10\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">10\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。另一方面，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>h\u003c/mi>\u003cmsup>\u003cmi>η\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cmi>m\u003c/mi>\u003c/mfrac>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|h\\eta\u0026#x27;|\n\\le\\frac{3L}{m}\\frac2{\\delta H}\\le1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于最后一项为非对角项，与对角部分正交，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmn>10\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>=\u003c/mo>\u003cmn>11\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>16.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(4)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\|\\nabla(u+w_R)\\|_F^2\\le10+1=11\u0026lt;16.\n\\tag{4}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的中间带内，梯度精确等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 或 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由于沿 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 方向恰有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个完整周期，两类区域都是有限个矩形，面积分别为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>δ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>θ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>R\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>δ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>θ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>R\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(5)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n(1-\\delta)\\theta|R|,\\qquad\n(1-\\delta)(1-\\theta)|R|.\n\\tag{5}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其余面积为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>R\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta|R|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，称为过渡区域。\u003c/p>\n\u003cp>现在对每个整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\delta=\\delta_N=\\frac1{(N+1)^2}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从零位移及整个活动区域 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 开始，按表中四行依次使用 (2)。每一步只在剩余梯度区域继续施工；已经得到的井区域和过渡区域均保留。每完成四步，活动梯度回到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。如此进行 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 轮，得到位移 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>这是有限次、有限个矩形上的显式施工。每个扰动都在相应矩形边界为零，因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>W\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nu_N\\in W^{1,\\infty}(\\Omega;\\mathbb R^2),\\qquad\nu_N|_{\\partial\\Omega}=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n每次施工区域中的旧梯度都是表中的精确母梯度，故 (4) 在整个递归过程中成立：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">ess sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/munder>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsqrt>\u003cmn>11\u003c/mn>\u003c/msqrt>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>4.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(6)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname*{ess\\,sup}_\\Omega\\|\\nabla u_N\\|_F\n\\le\\sqrt{11}\u0026lt;4.\n\\tag{6}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_N\\in\\mathcal A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>记第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 步后的活动面积为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_0=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。每一步的剩余比例至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3/4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以全部过渡区域的总面积 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>N\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munderover>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(7)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nb_N=\\delta_N\\sum_{s=0}^{4N-1}a_s\n\\le\\delta_N\\sum_{s=0}^\\infty(3/4)^s\n=4\\delta_N.\n\\tag{7}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n最终活动区域的梯度为零，其面积精确为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>4\u003c/mn>\u003c/msup>\u003c/mrow>\u003cmn>6\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>N\u003c/mi>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmn>6\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(8)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\na_{4N}=\\left(\\frac{(1-\\delta_N)^4}{6}\\right)^N\n\\le6^{-N}.\n\\tag{8}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n井区域的能量为零。过渡区域由 (6) 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"normal\">dist\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmn>32.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{dist}^2(\\nabla u_N,K)\n\\le\\|\\nabla u_N-A_2\\|_F^2\n\\le2\\|\\nabla u_N\\|_F^2+2\\|A_2\\|_F^2\n\\le32.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n零梯度区域的能量密度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。结合 (7)—(8)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmn>32\u003c/mn>\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>5\u003c/mn>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>128\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>5\u003c/mn>\u003cmsup>\u003cmn>6\u003c/mn>\u003cmi>N\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmo>⟶\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(9)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nE(u_N)\\le32b_N+5a_{4N}\n\\le\\frac{128}{(N+1)^2}+\\frac5{6^N}\n\\longrightarrow0.\n\\tag{9}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n能量非负，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>这个下确界不能达到。事实上，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u\\in K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 几乎处处，因而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\partial_2u_1=0,\\qquad \\partial_1u_2=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n沿竖直线对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、沿水平线对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使用一维基本定理和零边界迹，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_1=u_2=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u\\in K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 矛盾，因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\\notin K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>最后证明任意近最优序列的相分数都具有同一极限。对任意零边界的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\\in\\mathcal A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(10)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\int_\\Omega\\nabla u\\,dx=0,\\qquad\n\\int_\\Omega\\det\\nabla u\\,dx=0.\n\\tag{10}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n第一个等式来自分部积分。第二个等式先对光滑紧支撑位移由\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\det\\nabla u\n=\\partial_1(u_1\\partial_2u_2)\n-\\partial_2(u_1\\partial_1u_2)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n积分得到，再利用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>W\u003c/mi>\u003cmn>0\u003c/mn>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W^{1,2}_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的光滑逼近及行列式在梯度强 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 收敛下的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L^1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续性得到一般情形。\u003c/p>\n\u003cp>设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u_j)\\to0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M_j(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为题目规则选出的最近井。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\|M_j-\\nabla u_j\\|_{L^2}^2=E(u_j)\\to0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 (10) 及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Omega|=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(11)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\int_\\Omega M_j\\,dx\\longrightarrow0.\n\\tag{11}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n此外，二维行列式在 Frobenius 范数不超过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的球上满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>F\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>G\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>G\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|\\det F-\\det G|\\le4\\|F-G\\|_F,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为其导数为余子式矩阵，范数等于原矩阵范数。由于所有井的范数均小于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，再次利用 (10)，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsqrt>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msqrt>\u003cmo>⟶\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(12)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\left|\\int_\\Omega\\det M_j\\,dx\\right|\n\\le4\\sqrt{E(u_j)}\\longrightarrow0.\n\\tag{12}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_{i,j}=\\pi_i(u_j)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。将各井的对角元和行列式代入 (11)—(12)，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmspace width=\"2em\"/>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/munderover>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n3p_{1,j}+p_{2,j}-2p_{3,j}\u0026amp;\\longrightarrow0,\\\\\n2p_{2,j}+p_{3,j}-3p_{4,j}\u0026amp;\\longrightarrow0,\\\\\n2p_{2,j}-2p_{3,j}\u0026amp;\\longrightarrow0,\n\\end{aligned}\n\\qquad\n\\sum_{i=1}^4p_{i,j}=1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>o\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>o\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>o\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\np_{3,j}=p_{2,j}+o(1),\\qquad\np_{2,j}=3p_{1,j}+o(1),\\qquad\np_{4,j}=p_{2,j}+o(1),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n继而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>10\u003c/mn>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>o\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">10p_{1,j}=1+o(1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以整个序列必然满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n(p_{1,j},p_{2,j},p_{3,j},p_{4,j})\n\\longrightarrow\n\\left(\\frac1{10},\\frac3{10},\\frac3{10},\\frac3{10}\\right).\n}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n全部可能的极限构成这个单点集，而上述具体位移序列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 证明该极限确实能够实现。\u003c/p>\n","source":"assets/content/8475bf93bff23402dcd2a557a892da2171153f6e55b25bd45d2da50e00c7fc81.html"});
